def lenOfVDiagonal(grid):
    import sys
    from functools import lru_cache
    m, n = len(grid), len(grid[0])
    # Clockwise order of diagonal directions: SE -> SW -> NW -> NE -> SE,
    # so the clockwise turn of direction d is (d + 1) % 4.
    DIRS = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
    other = {0: 2, 2: 0}
    sys.setrecursionlimit(1 << 20)

    @lru_cache(maxsize=None)
    def go(r, c, d, need, can_turn):
        # (r, c) is an already-matched cell. Return the max number of
        # additional cells continuing the alternating 2,0,2,0 sequence.
        best = 0
        dr, dc = DIRS[d]
        nr, nc = r + dr, c + dc
        if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == need:
            best = max(best, 1 + go(nr, nc, d, other[need], can_turn))
        if can_turn:
            td = (d + 1) % 4
            tdr, tdc = DIRS[td]
            tr, tc = r + tdr, c + tdc
            if 0 <= tr < m and 0 <= tc < n and grid[tr][tc] == need:
                best = max(best, 1 + go(tr, tc, td, other[need], False))
        return best

    ans = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                for d in range(4):
                    ans = max(ans, 1 + go(r, c, d, 2, True))
    return ans
